#!/usr/bin/env bash
# Verify that the public API of the whole module matches api/v2.api.
#
# The baseline is apidiff export data generated by scripts/api-freeze.sh. Run
# that script (and commit api/v2.api) only when an API change is intentional.
set -euo pipefail

root=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

apidiff_version=${APIDIFF_VERSION:-v0.0.0-20260908205506-85c1c2202aba}
apidiff() { go run "golang.org/x/exp/cmd/apidiff@${apidiff_version}" "$@"; }

cd "$root"

apidiff -m -w "$tmp/current.api" github.com/sjlit/diago/v2
apidiff -m api/v2.api "$tmp/current.api"
